<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {adminPracticeSets,type AdminSet} from '@/api/admin-practice'
import {parseFilters,filterQuery,examLabels} from '@/practice/catalog-query'
import PracticeFilters from '@/components/practice/PracticeFilters.vue'
import {errorMessage} from '@/api/identity'
import {isSubjective} from '@/api/practice-subjective'
import {getGeneration} from '@/auth/token-session'
import '@/styles/practice.css'
const route=useRoute(),router=useRouter(),filters=ref(parseFilters(route.query,true)),rows=ref<AdminSet[]>([]),total=ref(0),busy=ref(false),error=ref('');let controller:AbortController|undefined,epoch=0
const statusLabel=(s:string)=>({DRAFT:'草稿',PUBLISHED:'已发布',UNLISTED:'已下架'})[s]||s
const editor=(r:AdminSet)=>'/admin/practice/'+(isSubjective(r.readingType)?'subjective/':'')+r.id
const typeLabel=(t:string)=>({WRITING:'写作',TRANSLATION:'翻译',LISTENING:'整套听力',MATCH:'长篇匹配',CLOZE:'选词填空'}[t]||'仔细阅读')
const examLabel=(r:AdminSet)=>r.metadata.sourceKind==='ORIGINAL'?'不适用 · 原创':examLabels[r.examCode]
const time=(r:AdminSet)=>r.metadata.sourceKind==='ORIGINAL'?'不适用 · 原创':`${r.metadata.year||'待补年份'}/${r.metadata.month||'待补月份'} 第${r.metadata.paperNo||'?'}套`
async function load(){const e=++epoch,g=getGeneration();controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{const data=await adminPracticeSets(filterQuery(filters.value),controller.signal);if(e===epoch&&g===getGeneration()){rows.value=data.items;total.value=data.total}}catch(ex){if(e===epoch&&!(ex instanceof DOMException&&ex.name==='AbortError'))error.value=errorMessage(ex)}finally{if(e===epoch)busy.value=false}}
async function apply(){const query=Object.fromEntries(filterQuery(filters.value));if(route.fullPath===router.resolve({path:route.path,query}).fullPath)await load();else await router.replace({query})}
function page(n:number){filters.value.page=n;void apply()}
watch(()=>route.query,()=>{filters.value=parseFilters(route.query,true);if(filters.value.source!=='PAST'&&['exam','year','month','paperNo'].some(key=>key in route.query)){const query={...route.query};for(const key of ['exam','year','month','paperNo'])delete query[key];void router.replace({query});return}void load()},{immediate:true});onBeforeUnmount(()=>{epoch++;controller?.abort()})
</script>
<template><section class="practice-page practice-admin-list"><header class="practice-heading"><div><h1>专项题组</h1><p>一篇材料，一组问题。整理并校对后再交给学员。</p></div><div class="practice-actions"><RouterLink to="/admin/practice/subjective/new">新建写作/翻译</RouterLink><RouterLink to="/admin/practice/papers">整卷管理</RouterLink><RouterLink to="/admin/practice/import">JSON导入</RouterLink><RouterLink class="button-primary" to="/admin/practice/new">新建题组</RouterLink></div></header><p class="practice-notice">真题目前支持四级仔细阅读、选词填空、长篇匹配、整套听力、写作与翻译；六级和考研题型为规划。原创题不按考试分类，考试类别与时间均不适用。</p><PracticeFilters v-model="filters" admin @apply="apply"/><div class="practice-admin-results" :aria-busy="busy"><p v-if="error" role="alert" class="practice-notice practice-error">{{error}}<button @click="load">重试</button></p><p class="practice-hint practice-admin-list-summary"><span>匹配 {{total}} 组 · 保存草稿不直接改变已发布内容</span><span class="practice-admin-list-status" role="status"><span v-if="busy">正在加载题组…</span></span></p><template v-if="rows.length"><div class="practice-table-wrap"><table class="practice-table"><thead><tr><th>题组名称</th><th>考试类别</th><th>题型</th><th>考试时间</th><th>题数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.metadata.title||'未命名题组'}}</strong><small>{{r.metadata.titleZh}} · {{r.metadata.sourceKind==='ORIGINAL'?'原创练习':'真题'}}</small></td><td>{{examLabel(r)}}</td><td>{{typeLabel(r.readingType)}}</td><td>{{time(r)}}</td><td>{{isSubjective(r.readingType)?1:r.questions.length}}</td><td><span class="practice-tag">{{statusLabel(r.status)}}</span></td><td><button class="button-primary" @click="router.push(editor(r))">编辑题组</button></td></tr></tbody></table></div><div class="practice-mobile-cards"><article v-for="r in rows" :key="r.id" class="practice-card"><span class="practice-tag">{{statusLabel(r.status)}} · {{examLabel(r)}} · {{isSubjective(r.readingType)?1:r.questions.length}}题</span><h2>{{r.metadata.title||'未命名题组'}}</h2><p class="practice-hint">{{r.metadata.titleZh}} · {{time(r)}}</p><button class="button-primary" @click="router.push(editor(r))">编辑题组</button></article></div></template><div v-else-if="!busy&&!error" class="practice-empty">没有匹配题组。可清空条件，或新建一篇材料对应的草稿。未开放的考试和题型暂不可录入。</div><nav class="practice-pagination" aria-label="题组分页"><label>每页 <select v-model.number="filters.pageSize" aria-label="每页条数" @change="filters.page=1;apply()"><option :value="5">5组</option><option :value="10">10组</option><option :value="20">20组</option></select></label><div class="practice-actions"><button :disabled="busy||filters.page<=1" @click="page(filters.page-1)">上一页</button><span>第 {{filters.page}} / {{Math.max(1,Math.ceil(total/filters.pageSize))}} 页</span><button :disabled="busy||filters.page*filters.pageSize>=total" @click="page(filters.page+1)">下一页</button></div></nav></div></section></template>

